PRIORITY={'Q02','Q05','Q18','Q19','Q25','Q26','Q28','Q42','Q44','Q46','Q47','Q48'}
E=lambda value:html.escape(str(value),quote=True)
BY_ID={p['id']:p for p in PROCESSES}
assert len(BY_ID)==len(PROCESSES)==34
assert len({q[0] for q in QUESTIONS})==len(QUESTIONS)==49
assert all(pid in BY_ID for _,pid,_ in QUESTIONS)


def R(value):
    def link(m):
        ref=m[0]
        if ref in BY_ID:return '<a href="#process-'+ref+'">'+ref+'</a>'
        if ref in {q[0] for q in QUESTIONS}:return '<a href="#question-'+ref+'">'+ref+'</a>'
        return ref
    return re.sub(r'\b(?:[SWCGLO][0-9]{2}|Q[0-9]{2})\b',link,E(value))

def ul(values):return '<ul>'+''.join('<li>'+R(v)+'</li>' for v in values)+'</ul>' 
def question_row(q):
    qid,pid,text=q
    return '<li id="question-'+qid+'" data-question="'+qid+'"><span class="question-id">'+qid+'</span><div><p>'+E(text)+'</p><a href="#process-'+pid+'">'+pid+' · '+E(BY_ID[pid]['title'])+'</a>'+('<span class="decision-priority">Prioritize before December</span>' if qid in PRIORITY else '')+'</div></li>'


def process_card(p):
    pid=p['id'];qs=[q for q in QUESTIONS if q[1]==pid]
    out='<details class="process-card" id="process-'+pid+'" data-process="'+pid+'" data-phase="'+p['phase']+'"><summary><span class="process-id">'+pid+'</span><span class="process-heading"><strong>'+E(p['title'])+'</strong><small>'+E(p['stages'])+'</small></span><span class="process-question-count">'+str(len(qs))+' open '+('question' if len(qs)==1 else 'questions')+'</span></summary><div class="process-body">'
    out+='<p class="process-goal">'+E(p['goal'])+'</p><div class="process-meta"><div><h4>When this starts</h4><p>'+E(p['trigger'])+'</p></div><div><h4>Suggested operating lead</h4><p>'+E(p['lead'])+'</p><small>Confirm named ownership/backup in Q41. Approved role authority still applies.</small></div><div><h4>Connected teams</h4><p>'+E(p['partners'])+'</p></div></div>'
    out+='<section class="approved-foundation"><h4>Approved foundation</h4>'+ul(p['approved'])+'</section><h4>Input quality to inspect</h4>'+ul(p['inputs'])
    out+='<h4>Draft operating procedure</h4><ol class="process-method">'+''.join('<li>'+R(x)+'</li>' for x in p['steps'])+'</ol>'
    out+='<div class="inspection"><h4>When to inspect</h4><p>'+R(p['inspect'])+'</p></div><h4>Exception and recovery route</h4><p>'+E(p['exception'])+'</p>'
    out+='<h4>Completion and receiving handoff</h4><p>'+R(p['handoff'])+'</p><h4>Measures to use</h4>'+ul(p['metrics'])+'<p class="metric-note">Suggested measures; targets, report owners and exact definitions remain to agree in Q44–Q45.</p>'
    out+='<section class="process-questions"><h4>Questions to resolve</h4><ol class="question-list">'+''.join(question_row(q).replace('id="question-'+q[0]+'"','') for q in qs)+'</ol></section>'
    out+='<p class="source-links"><strong>Approved source:</strong> '+ ' · '.join('<a href="index.html#'+anchor+'">'+E(label)+'</a>' for anchor,label in p['refs'])+'</p><p class="process-return"><a href="#phase-'+p['phase']+'">Back to this group</a> · <a href="#open-questions">All open questions</a></p></div></details>'
    return out


def page(header):
    out='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Working draft of DDN GTM operating processes, inspection rhythms, handoffs and questions for the approved sales stages."><title>GTM Processes · GTM Process</title><link rel="stylesheet" href="assets/navigation.css"><link rel="stylesheet" href="assets/learning.css"><link rel="stylesheet" href="assets/processes.css"><script src="assets/processes.js" defer></script></head><body id="top" data-page="processes"><a class="skip" href="#main">Skip to content</a>'''+header('processes')
    out+='''<div class="process-shell"><main id="main"><header class="process-hero"><p class="eyebrow">GTM operations · Working draft · October 28, 2026</p><h1>GTM Processes</h1><p class="lead">The operating playbook around the approved sales stages: who supports the work, what good input looks like, when to inspect, and how teams hand work forward.</p><div class="hero-meta"><span class="pill">34 process drafts</span><a class="pill" href="#open-questions">49 open questions</a><span class="pill">Planned implementation · December 2026</span></div><p class="draft-boundary">The sales-stage foundation is signed off. Procedures, suggested operating leads and new inspection proposals on this page are a first draft for review. Approved controls and your confirmed review cadence are identified separately. Answers here will refine the operating playbook; any proposed system change will need its own explicit decision.</p></header>'''
    out+='<nav class="process-jumps" aria-label="Process groups">'+''.join('<a href="#phase-'+key+'"><strong>'+title+'</strong><span>'+str(sum(p['phase']==key for p in PROCESSES))+' processes</span></a>' for key,title,_ in PHASES)+'</nav>'
    out+='''<details class="operating-rhythm" id="inspection-rhythm"><summary>Confirmed inspection rhythm and decision points</summary><div class="rhythm-body"><p>Confirmed October 28. Event-based controls still apply when the event occurs; a scheduled review does not replace a stage gate.</p><div class="table-scroll"><table><thead><tr><th>Inspection</th><th>When</th><th>Purpose and owner</th></tr></thead><tbody><tr><td>CRO and sales leader forecast</td><td>Weekly</td><td>CRO and sales leaders inspect confidence, changes, Commit risk and required actions.</td></tr><tr><td>Sales leader and team</td><td>Weekly</td><td>Leader and AE/SE inspect customer progress, evidence, risks and owned actions.</td></tr><tr><td>Pipeline reviews</td><td>Every two weeks, including sales leader/team reviews</td><td>Inspect pipeline creation, qualification, coverage, stage progression and stalled work.</td></tr><tr><td>Partner group review</td><td>Weekly</td><td>Inspect participating partners, co-selling actions, commercial chains and credit exceptions.</td></tr><tr><td>Salesforce opportunity updates</td><td>At least once a week</td><td>Opportunity owners maintain current facts and actions. OM/booked protections apply; historical closed-record scope is Q42.</td></tr><tr><td>Stage, POC, NVIDIA and order controls</td><td>At the applicable event or gate</td><td>Responsible owners inspect required evidence; OM reviews submission, rejection/resubmission and booking.</td></tr></tbody></table></div><p>Daily queue checks, post-booking value reviews, metric targets and other service times below are marked as proposals or questions. Weekly AE/SE freshness checks and the Win/Loss/booking commitments already in the foundation remain in force.</p></div></details>'''
    out+='''<section class="process-tools" aria-label="Find a process"><div class="process-filter-grid"><div><label for="process-search">Search processes or questions</label><input type="search" id="process-search" placeholder="Try contract, partner, renewal, POC, Q25…" autocomplete="off"></div><div><label for="process-phase">Lifecycle group</label><select id="process-phase"><option value="all">All groups</option>'''+''.join('<option value="'+key+'">'+title+'</option>' for key,title,_ in PHASES)+'''</select></div><button id="reset-processes" type="button">Reset</button></div><div class="process-tool-footer"><p id="process-count" role="status" aria-live="polite">34 processes in six groups</p><div><button id="expand-processes" type="button">Expand matching processes</button><button id="collapse-processes" type="button">Collapse processes</button><button id="print-processes" type="button">Print this view</button></div></div></section><p id="process-empty" hidden>No matching processes. Try another term or reset the filters.</p><section id="process-library" aria-label="Draft operating processes">'''
    for key,title,description in PHASES:
        rows=[p for p in PROCESSES if p['phase']==key]
        out+='<details class="process-phase" id="phase-'+key+'" data-phase-group="'+key+'"><summary><span><strong>'+title+'</strong><small>'+E(description)+'</small></span><span class="phase-count">'+str(len(rows))+' processes</span></summary><div class="phase-body"><p class="phase-status">Working draft · click a process to review its inputs, steps, inspection, handoff and questions.</p>'+''.join(process_card(p) for p in rows)+'</div></details>'
    out+='''</section><section class="question-register" id="open-questions"><header><p class="eyebrow">Decisions for the working draft</p><h2>Open questions</h2><p>Reply in the conversation using the question IDs; we will update the related process as decisions are made. These are operating decisions, not automatic additions to the signed-off build.</p><p><strong>Suggested first decisions:</strong> MAP cutover (Q02), intake service times (Q05), forecast scope (Q18–Q19), OM review/queues (Q25–Q26), weekly update scope (Q42), and December readiness (Q47–Q48).</p><button id="copy-questions" type="button">Copy all questions</button><p id="copy-status" role="status" aria-live="polite"></p><textarea id="question-copy-fallback" readonly hidden aria-label="All questions to copy"></textarea></header>'''
    for key,title,_ in PHASES:
        qs=[q for q in QUESTIONS if BY_ID[q[1]]['phase']==key]
        out+='<details class="question-group" id="questions-'+key+'"><summary>'+title+' <span>'+str(len(qs))+' questions</span></summary><ol class="question-list">'+''.join(question_row(q) for q in qs)+'</ol></details>'
    out+='''</section><footer class="process-footer"><p>Draft basis: <a href="index.html#one-slide">approved sales stages</a>, <a href="index.html#changes-2026-10-21">October 21 requirements</a>, <a href="enablement.html">enablement</a>, <a href="permissions.html">access and permissions</a>, and the October 28 operating cadence confirmed in this conversation. Existing system requirements and downloads retain their approved scope.</p></footer></main></div><a class="backtop" href="#top">↑ Back to top</a></body></html>'''
    return out
